def jump(nums):
    jumps = 0; end = 0; far = 0
    for i in range(len(nums) - 1):
        far = max(far, i + nums[i])
        if i == end: jumps += 1; end = far
    return jumps

solution.cpp:
int jump(vector<int>& a) {
    int j = 0, end = 0, far = 0;
    for (int i = 0; i + 1 < (int)a.size(); i++) { far = max(far, i + a[i]); if (i == end) { j++; end = far; } }
    return j;
}
